@dataclass(frozen=True)
class Assignment:
    section: str
    key: str
    text: str
    interp: bool
    where: str


class Loader:
    def __init__(self, ds: DataSet):
        self.ds = ds
        self.assignments: list[Assignment] = []
        self.includes: list[str] = []
        self._stack: list[str] = []

    def load(self, cid: str) -> "Loader":
        self._file(f"configs/{cid}.conf", self.ds.config_text(cid))
        return self

    def _file(self, label: str, text: str) -> None:
        if label in self._stack:
            raise IncludeError(f"{label} includes itself through {' -> '.join(self._stack)}")
        self._stack.append(label)
        # The whole file is read (syntax.md) before any of it is applied.
        items = []
        try:
            for line in parse_lines(text):
                if line.kind == "assign":
                    where = f"{label} line {line.lineno}"
                    items.append((line, where, parse_value(line.value, where)))
                else:
                    items.append((line, f"{label} line {line.lineno}", None))
        except ParseError as e:
            if str(e).startswith(label):
                raise
            raise ParseError(f"{label} {e}") from None
        section = "main"  # a file always starts in main; its sections do not leak out
        for line, where, parsed in items:
            if line.kind == "section":
                section = line.name
            elif line.kind == "include":
                self._include(line.name, where)
            else:
                value, interp = parsed
                self.assignments.append(Assignment(section, line.name, value, interp, where))
        self._stack.pop()

    def _include(self, name: str, where: str) -> None:
        try:
            text = self.ds.shared_text(name)
        except IncludeError as e:
            raise IncludeError(f"{where}: {e}") from None
        if name not in self.includes:
            self.includes.append(name)
        self._file(name, text)
